create or replace function public.admin_attributes_bundle(p_token text,p_search text default '') returns jsonb language plpgsql security definer set search_path=public as $$ declare v_admin public."AdminUser"%rowtype; v_q text:=lower(trim(coalesce(p_search,''))); begin v_admin:=public._admin_session_user(p_token); if v_admin.role not in ('SUPER_ADMIN'::"AdminRole",'EDITOR'::"AdminRole") then raise exception 'forbidden'; end if; return jsonb_build_object('definitions',(select coalesce(jsonb_agg(to_jsonb(x) order by x."sortOrder",x.code),'[]'::jsonb) from (select d.*,count(v."productId")::int as "usageCount" from public."ProductAttributeDefinition" d left join public."ProductAttributeValue" v on v."definitionId"=d.id where v_q='' or lower(concat_ws(' ',d.code,d."nameFa",d."nameTr",d."nameEn",d."nameAr",d."groupFa",d."groupEn")) like '%'||v_q||'%' group by d.id) x),'products',(select coalesce(jsonb_agg(jsonb_build_object('id',p.id,'sku',p.sku,'nameFa',p."nameFa",'nameTr',p."nameTr",'nameEn',p."nameEn",'nameAr',p."nameAr") order by p."nameEn",p.sku),'[]'::jsonb) from public."Product" p where p."isPublished"=true)); end $$;
revoke all on function public.admin_attributes_bundle(text,text) from public;
grant execute on function public.admin_attributes_bundle(text,text) to anon,authenticated,service_role;